import math
import unittest

from solution import locate_signal_extremes


class LocateSignalExtremesTests(unittest.TestCase):
    def test_empty_list(self):
        self.assertIsNone(locate_signal_extremes([]))

    def test_extremes_first_occurrences_and_exact_keys(self):
        samples = [3, -2.5, 8, 8.0, -2.5, 4]
        before = list(samples)
        result = locate_signal_extremes(samples)
        self.assertEqual(
            result,
            {"highest": 8, "highest_index": 2, "lowest": -2.5, "lowest_index": 1},
        )
        self.assertEqual(
            set(result), {"highest", "highest_index", "lowest", "lowest_index"}
        )
        self.assertEqual(samples, before)

    def test_single_value_is_both_extremes(self):
        value = 4.25
        self.assertEqual(
            locate_signal_extremes([value]),
            {"highest": value, "highest_index": 0, "lowest": value, "lowest_index": 0},
        )

    def test_equal_numeric_values_return_first_value_unchanged(self):
        samples = [2, 2.0]
        result = locate_signal_extremes(samples)
        self.assertIs(type(result["highest"]), int)
        self.assertIs(type(result["lowest"]), int)
        self.assertEqual(result["highest_index"], 0)
        self.assertEqual(result["lowest_index"], 0)

    def test_non_list_argument(self):
        for bad in (None, (1, 2), "12", {1, 2}):
            with self.subTest(bad=bad):
                with self.assertRaises(TypeError):
                    locate_signal_extremes(bad)

    def test_invalid_element_types_include_booleans(self):
        for bad in (True, False, None, "3", complex(1, 0), [1]):
            with self.subTest(bad=bad):
                with self.assertRaises(TypeError):
                    locate_signal_extremes([0, bad])

    def test_non_finite_elements(self):
        for bad in (math.inf, -math.inf, math.nan):
            with self.subTest(bad=bad):
                with self.assertRaises(ValueError):
                    locate_signal_extremes([1, bad])


if __name__ == "__main__":
    unittest.main()

